; EXODUS.BIN: Ultima III (Origin 1983, PC version by James R. Van Artsdalen).
; Generated by tools/gen.py; tools/build.py builds it (MASM, LINK, then the image from 0100).
; PARTY: names, status lines, hit points, food, poison (6B91-7458).
;
; The routines that work on the four player records (Players, 64 bytes each, docs/FORMATS.md 6):
; saving the game (SaveGame), damage and death (HurtPlayer), PrintName, IsUp, the "All Players Out!"
; check (CheckAllOut), AskPlayer, the four status boxes on the right (StatusLine, the player numbers
; DrawPlayerNums), the Ztats screen (ShowZtats), the per-turn upkeep (PartyUpkeep: magic points by class, food,
; poison, hit point regeneration; SpendFood prints "Starving!"), the screen inversions used as
; "flashes" everywhere (FlashPlayer a status box, FlashView the map window, InvertPlayerNum a player number), the
; checks before a move (AgainstWind the wind for the frigate, CheckTerrain the terrain: force field, lava),
; the whirlpool (MoveWhirlpool) and two string helpers for typed words (UpcaseBuf, MatchWord).
; The flashes write the CGA memory directly through the segment kept at ds:[4F39h].
CODE SEGMENT BYTE PUBLIC
ASSUME CS:CODE, DS:CODE, ES:CODE, SS:CODE
EXTRN CursorCol:BYTE
EXTRN CursorRow:BYTE
EXTRN WindDir:BYTE
EXTRN PrintStr:NEAR
EXTRN PutChar:NEAR
EXTRN Random:NEAR
EXTRN KeyReady:NEAR
EXTRN ReadKey:NEAR
EXTRN PrintBcdWord:NEAR
EXTRN PrintBcdByte:NEAR
EXTRN PrintDigit:NEAR
EXTRN Sound:NEAR
EXTRN WhirlpoolX:BYTE
EXTRN WhirlpoolDX:BYTE
EXTRN WhirlpoolDY:BYTE
EXTRN PartyTile:BYTE
EXTRN Location:BYTE
EXTRN PartySize:BYTE
EXTRN Players:BYTE
EXTRN Player4:BYTE
EXTRN PlayerXY:BYTE
EXTRN SaveSosaria:NEAR
EXTRN SaveParty:NEAR
EXTRN Whirlpool:NEAR
EXTRN PrintMsg:NEAR
EXTRN ScrollMsg:NEAR
EXTRN BuildView:NEAR
EXTRN MapCellAddr:NEAR
EXTRN SavedLocation:BYTE
EXTRN UpkeepTick:BYTE
EXTRN RegenTick:BYTE
EXTRN WhirlpoolTick:BYTE
EXTRN MsgNoOneThere:BYTE
EXTRN MsgAllPlayersOut:BYTE
EXTRN MsgShipDestroyed:BYTE
EXTRN MsgStarving:BYTE
EXTRN MsgPoisoned:BYTE
EXTRN NameTbl:BYTE
EXTRN MsgZtStr:BYTE
EXTRN MsgZtDex:BYTE
EXTRN MsgZtInt:BYTE
EXTRN MsgZtWis:BYTE
EXTRN MsgZtHP:BYTE
EXTRN MsgZtHM:BYTE
EXTRN MsgZtGold:BYTE
EXTRN MsgZtExp:BYTE
EXTRN MsgZtGems:BYTE
EXTRN MsgZtKeys:BYTE
EXTRN MsgZtPowd:BYTE
EXTRN MsgZtTrch:BYTE
EXTRN MsgCardOfDeath:BYTE
EXTRN MsgCardOfSol:BYTE
EXTRN MsgCardOfLove:BYTE
EXTRN MsgCardOfMoons:BYTE
EXTRN MsgMarkOfForce:BYTE
EXTRN MsgMarkOfFire:BYTE
EXTRN MsgMarkOfSnake:BYTE
EXTRN MsgMarkOfKings:BYTE
EXTRN MsgZtWeapon:BYTE
EXTRN MsgZtArmour:BYTE
EXTRN MsgZtWeapons:BYTE
EXTRN MsgZtHandsArmour:BYTE
EXTRN MsgZtSkin:BYTE
EXTRN MsgStatM:BYTE
EXTRN MsgStatL:BYTE
EXTRN MsgStatH:BYTE
EXTRN MsgStatF:BYTE
PUBLIC SaveGame
PUBLIC HurtPlayer
PUBLIC PrintName
PUBLIC IsUp
PUBLIC CheckAllOut
PUBLIC FlushKeys
PUBLIC AskPlayer
PUBLIC StatusLine
PUBLIC DrawPlayerNums
PUBLIC ShowZtats
PUBLIC WaitMore
PUBLIC PartyUpkeep
PUBLIC FlashPlayer
PUBLIC FlashView
PUBLIC InvertPlayerNum
PUBLIC AgainstWind
PUBLIC Hang
PUBLIC CheckTerrain
PUBLIC MoveWhirlpool
PUBLIC UpcaseBuf
PUBLIC MatchWord
;------------------------------------------------------------------------------
; SaveGame: write PARTY.ULT (SaveParty), and SOSARIA.ULT too (SaveSosaria) when the party is on
; the surface (Location 0, or 80h with SavedLocation = 0). Location is set to 0 while the file is
; written, so the saved party always says "Sosaria". Called when a player dies, when all are
; out and at the end of the game. Uses: nothing (saves AX and flags).
;------------------------------------------------------------------------------
SaveGame:	pushf	;@6B91
	push ax	;@6B92
	cmp byte ptr Location, 0	;@6B93
	je SaveGame_WithMap	;@6B98
	cmp byte ptr Location, 80h	; 80h: a fight	;@6B9A
	jne SaveGame_PartyOnly	;@6B9F
	cmp byte ptr SavedLocation, 0	;@6BA1
	je SaveGame_WithMap	;@6BA6
SaveGame_PartyOnly:	mov al, byte ptr Location	;@6BA8
	mov byte ptr Location, 0	;@6BAB
	call SaveParty	;@6BB0
	mov byte ptr Location, al	;@6BB3
SaveGame_Done:	pop ax	;@6BB6
	popf	;@6BB7
	ret	;@6BB8
SaveGame_WithMap:	mov al, byte ptr Location	;@6BB9
	mov byte ptr Location, 0	;@6BBC
	call SaveSosaria	;@6BC1
	mov byte ptr Location, al	;@6BC4
	jmp SaveGame_Done	;@6BC7
;------------------------------------------------------------------------------
; HurtPlayer: subtract AL (BCD, 0-99) from the hit points of the player at BX. Below
; zero the player dies: status 'D', hit points 0, and the game is saved. Redraws the status.
; In: AL, BX. Out: AL = 0FFh if the player died, else 0. Uses: nothing else.
;------------------------------------------------------------------------------
HurtPlayer:	pushf	;@6BC9
	push cx	;@6BCA
	push ax	;@6BCB
	mov cl, al	;@6BCC
	mov ax, word ptr [bx+1Ah]	; hit points (BCD word)	;@6BCE
	sub al, cl	;@6BD1
	das	;@6BD3
	xchg al, ah	;@6BD4
	sbb al, 0	;@6BD6
	das	;@6BD8
	xchg al, ah	;@6BD9
	mov word ptr [bx+1Ah], ax	;@6BDB
	mov ch, 0	;@6BDE
	jae HurtPlayer_Status	;@6BE0
	mov byte ptr [bx+11h], 44h	; status 'D' dead	;@6BE2
	mov word ptr [bx+1Ah], 0	;@6BE6
	call SaveGame	;@6BEB
	mov ch, 0FFh	;@6BEE
HurtPlayer_Status:	call StatusLine	;@6BF0
	pop ax	;@6BF3
	mov al, ch	;@6BF4
	pop cx	;@6BF6
	popf	;@6BF7
	ret	;@6BF8
	db 0C3h	; a stray ret nothing reaches	;@6BF9
;------------------------------------------------------------------------------
; PrintName: print name number AL-1 of NameTbl (1-88h; 0 would read entry -1) in the message
; window. AL = shape+1 for tiles; weapons are 41h+index, armours 51h+index (FORMATS.md 2).
; In: AL. Uses: nothing.
;------------------------------------------------------------------------------
PrintName:	pushf	;@6BFA
	push bx	;@6BFB
	push si	;@6BFC
	cmp al, 88h	; 136 names	;@6BFD
	ja PrintName_Done	;@6BFF
	mov bl, al	;@6C01
	dec bl	;@6C03
	mov bh, 0	;@6C05
	shl bx, 1	;@6C07
	mov si, word ptr NameTbl[bx]	;@6C09
	call PrintMsg	;@6C0D
PrintName_Done:	pop si	;@6C10
	pop bx	;@6C11
	popf	;@6C12
	ret	;@6C13
;------------------------------------------------------------------------------
; IsUp: can the player at BX act? ZF set (AL = 0) when the status is Good or Poisoned,
; ZF clear (AL = 0FFh) for Dead or Ashes. In: BX. Out: AL, ZF.
;------------------------------------------------------------------------------
IsUp:	pushf	;@6C14
	mov al, 0	;@6C15
	cmp byte ptr [bx+11h], 47h	; status 'G' good	;@6C17
	je IsUp_Done	;@6C1B
	cmp byte ptr [bx+11h], 50h	; 'P' poisoned	;@6C1D
	je IsUp_Done	;@6C21
	mov al, 0FFh	;@6C23
IsUp_Done:	popf	;@6C25
	cmp al, 0	;@6C26
	ret	;@6C28
;------------------------------------------------------------------------------
; CheckAllOut: if none of the four players is up, print "All Players Out!", save the
; game and stop for good (Hang). Otherwise return. Uses: nothing.
;------------------------------------------------------------------------------
CheckAllOut:	pushf	;@6C29
	push ax	;@6C2A
	push bx	;@6C2B
	push cx	;@6C2C
	lea bx, Players	;@6C2D
	mov cx, 4	;@6C31
CheckAllOut_Loop:	call IsUp	;@6C34
	je CheckAllOut_Done	;@6C37
	add bx, 40h	;@6C39
	loop CheckAllOut_Loop	;@6C3C
	call StatusLine	;@6C3E
	lea si, MsgAllPlayersOut	; "All Players Out!"	;@6C41
	call PrintMsg	;@6C45
	call SaveGame	;@6C48
	jmp Hang	; hang	;@6C4B
CheckAllOut_Done:	pop cx	;@6C4E
	pop bx	;@6C4F
	pop ax	;@6C50
	popf	;@6C51
	ret	;@6C52
;------------------------------------------------------------------------------
; FlushKeys: read and drop every key waiting. Location is 1 meanwhile, so that KeyReady skips
; the idle animation (it tests Location = Location). Uses: nothing.
;------------------------------------------------------------------------------
FlushKeys:	pushf	;@6C53
	push ax	;@6C54
	push bx	;@6C55
	mov bh, byte ptr Location	;@6C56
	mov byte ptr Location, 1	;@6C5A
FlushKeys_Loop:	sti	; let the keyboard interrupt in	;@6C5F
	nop	;@6C60
	nop	;@6C61
	nop	;@6C62
	cli	;@6C63
	call KeyReady	;@6C64
	je FlushKeys_Done	;@6C67
	call ReadKey	;@6C69
	jmp FlushKeys_Loop	;@6C6C
FlushKeys_Done:	mov byte ptr Location, bh	;@6C6E
	pop bx	;@6C72
	pop ax	;@6C73
	popf	;@6C74
	ret	;@6C75
;------------------------------------------------------------------------------
; AskPlayer: read a player number 0-4 (other keys beep), echo it; Esc or 0 = nobody. An empty
; slot prints "No one there!" and counts as nobody.
; Out: AL = 1-4 or 0, ZF set when nobody; AH kept; BX = the player's record. Uses: BX.
;------------------------------------------------------------------------------
AskPlayer:	push cx	;@6C76
	push si	;@6C77
	mov ch, ah	;@6C78
AskPlayer_Key:	call ReadKey	;@6C7A
	cmp ax, 11Bh	; Esc	;@6C7D
	je AskPlayer_Esc	;@6C80
	sub al, 30h	; '0'	;@6C82
	cmp al, 4	;@6C84
	ja AskPlayer_Bad	;@6C86
	call PrintDigit	;@6C88
	mov ah, 40h	; record size	;@6C8B
	mov cl, al	;@6C8D
	dec al	;@6C8F
	js AskPlayer_Done	; '0': nobody	;@6C91
	mul ah	;@6C93
	mov bx, ax	;@6C95
	lea bx, Players[bx]	;@6C97
	cmp byte ptr [bx], 0	; empty slot (no name)	;@6C9B
	jne AskPlayer_Done	;@6C9E
	mov cl, 0	;@6CA0
	lea si, MsgNoOneThere	; "No one there!"	;@6CA2
	call PrintMsg	;@6CA6
	mov al, 0FEh	; error beep	;@6CA9
	call Sound	;@6CAB
AskPlayer_Done:	mov ax, cx	;@6CAE
	call ScrollMsg	;@6CB0
	cmp al, 0	;@6CB3
	pop si	;@6CB5
	pop cx	;@6CB6
	ret	;@6CB7
AskPlayer_Bad:	mov al, 0FEh	;@6CB8
	call Sound	;@6CBA
	jmp AskPlayer_Key	;@6CBD
AskPlayer_Esc:	mov cl, 0	;@6CBF
	jmp AskPlayer_Done	;@6CC1
;------------------------------------------------------------------------------
; StatusLine: redraw the four status boxes (columns 19h-27h, rows 4n+1 to 4n+3 for player n
; = 0-3; row 4n is the frame with the number): the name centred and the status letter at
; column 26h; sex, race, class, " M:" magic points, " L:" level; "H:" hit points, " F:" food.
; The level is the high byte of the experience + 1 (BCD, at most 99). Empty slots are
; skipped. Uses: nothing (the cursor is kept).
;------------------------------------------------------------------------------
StatusLine:	pushf	;@6CC3
	push ax	;@6CC4
	push bx	;@6CC5
	push cx	;@6CC6
	push si	;@6CC7
	push word ptr CursorCol	;@6CC8
	mov cx, 4	;@6CCC
	lea bx, Players	;@6CCF
StatusLine_Loop:	cmp byte ptr [bx], 0	;@6CD3
	je StatusLine_Next	;@6CD6
	mov al, 4	;@6CD8
	sub al, cl	; player 0-3	;@6CDA
	call PrintNameCentered	;@6CDC
	mov byte ptr CursorCol, 26h	;@6CDF
	mov al, byte ptr [bx+11h]	; status letter	;@6CE4
	call PutChar	;@6CE7
	mov byte ptr CursorCol, 19h	;@6CEA
	inc byte ptr CursorRow	;@6CEF
	mov al, byte ptr [bx+18h]	; sex	;@6CF3
	call PutChar	;@6CF6
	mov al, byte ptr [bx+16h]	; race	;@6CF9
	call PutChar	;@6CFC
	mov al, byte ptr [bx+17h]	; class	;@6CFF
	call PutChar	;@6D02
	lea si, MsgStatM	; " M:"	;@6D05
	call PrintStr	;@6D09
	mov al, byte ptr [bx+19h]	; magic points	;@6D0C
	call PrintBcdByte	;@6D0F
	lea si, MsgStatL	; " L:"	;@6D12
	call PrintStr	;@6D16
	mov al, byte ptr [bx+1Fh]	; experience / 100	;@6D19
	add al, 1	;@6D1C
	daa	;@6D1E
	jae StatusLine_Level	;@6D1F
	mov al, 99h	;@6D21
StatusLine_Level:	call PrintBcdByte	;@6D23
	inc byte ptr CursorRow	;@6D26
	mov byte ptr CursorCol, 19h	;@6D2A
	lea si, MsgStatH	; "H:"	;@6D2F
	call PrintStr	;@6D33
	mov ax, word ptr [bx+1Ah]	; hit points	;@6D36
	call PrintBcdWord	;@6D39
	lea si, MsgStatF	; " F:"	;@6D3C
	call PrintStr	;@6D40
	mov ax, word ptr [bx+21h]	; food	;@6D43
	call PrintBcdWord	;@6D46
StatusLine_Next:	add bx, 40h	;@6D49
	loop StatusLine_Loop	;@6D4C
	pop word ptr CursorCol	;@6D4E
	pop si	;@6D52
	pop cx	;@6D53
	pop bx	;@6D54
	pop ax	;@6D55
	popf	;@6D56
	ret	;@6D57
;------------------------------------------------------------------------------
; DrawPlayerNums: print the four player numbers between the moon-symbol brackets
; (characters 10h, 11h) at row 4n, column 1Eh, in the frame of the status boxes.
; Uses: CX (returns 0).
;------------------------------------------------------------------------------
DrawPlayerNums:	pushf	;@6D58
	push ax	;@6D59
	mov cx, 4	;@6D5A
DrawPlayerNums_Loop:	mov al, cl	;@6D5D
	dec al	;@6D5F
	shl al, 1	;@6D61
	shl al, 1	;@6D63
	mov byte ptr CursorRow, al	;@6D65
	mov byte ptr CursorCol, 1Eh	;@6D68
	mov al, 10h	;@6D6D
	call PutChar	;@6D6F
	mov al, cl	;@6D72
	call PrintDigit	;@6D74
	mov al, 11h	;@6D77
	call PutChar	;@6D79
	loop DrawPlayerNums_Loop	;@6D7C
	pop ax	;@6D7E
	popf	;@6D7F
	ret	;@6D80
;------------------------------------------------------------------------------
; PrintNameCentered: print the name at BX (NUL ended) centred in the status box of player AL
; (0-3): column (3Fh - length) / 2, row 4 * AL + 1. In: AL, BX. Uses: nothing.
;------------------------------------------------------------------------------
PrintNameCentered:	pushf	;@6D81
	push ax	;@6D82
	push cx	;@6D83
	push si	;@6D84
	push di	;@6D85
	cld	;@6D86
	mov ah, al	;@6D87
	mov di, bx	;@6D89
	mov si, di	;@6D8B
	mov al, 0	;@6D8D
	mov cx, 1Fh	;@6D8F
	repne scasb	; CX = 1Fh - length - 1	;@6D92
	add cl, 21h	;@6D94
	shr cl, 1	;@6D97
	mov byte ptr CursorCol, cl	;@6D99
	shl ah, 1	;@6D9D
	shl ah, 1	;@6D9F
	add ah, 1	;@6DA1
	mov byte ptr CursorRow, ah	;@6DA4
	call PrintStr	;@6DA8
	pop di	;@6DAB
	pop si	;@6DAC
	pop cx	;@6DAD
	pop ax	;@6DAE
	popf	;@6DAF
	ret	;@6DB0
; The strings of the bits of record byte 0Eh, bit 7 first: Mark of Kings, Snake, Fire, Force,
; Card of Death, Moons, Sol, Love.
MarkCardNames	dw MsgMarkOfKings	;@6DB1
	dw MsgMarkOfSnake	;@6DB3
	dw MsgMarkOfFire	;@6DB5
	dw MsgMarkOfForce	;@6DB7
	dw MsgCardOfDeath	;@6DB9
	dw MsgCardOfMoons	;@6DBB
	dw MsgCardOfSol	;@6DBD
	dw MsgCardOfLove	;@6DBF
;------------------------------------------------------------------------------
; ShowZtats: the Ztats of a player, in the message window: name, Str, Dex, Int, Wis,
; H.P., then one line per key (WaitMore; Esc ends): H.M., Gold, Exp, Gems, Keys, Powd, Trch,
; the marks and cards owned, the weapon readied and armour worn, then the weapons and
; armours owned as "nn-Name-(key)" (Hands and Skin are always there: fixed strings).
; The player's number is inverted meanwhile (InvertPlayerNum).
; In: DH = '1'-'4', DI = the record. Uses: CX (not saved).
;------------------------------------------------------------------------------
ShowZtats:	pushf	;@6DC1
	push ax	;@6DC2
	push bx	;@6DC3
	push si	;@6DC4
	mov al, dh	;@6DC5
	sub al, 30h	; '0'	;@6DC7
	call InvertPlayerNum	;@6DC9
	lea si, [di]	; the name	;@6DCC
	call PrintMsg	;@6DCE
	lea si, MsgZtStr	; "Str..."	;@6DD1
	call PrintMsg	;@6DD5
	mov al, byte ptr [di+12h]	; strength	;@6DD8
	call PrintBcdByte	;@6DDB
	lea si, MsgZtDex	; "Dex..."	;@6DDE
	call PrintMsg	;@6DE2
	mov al, byte ptr [di+13h]	; dexterity	;@6DE5
	call PrintBcdByte	;@6DE8
	lea si, MsgZtInt	; "Int..."	;@6DEB
	call PrintMsg	;@6DEF
	mov al, byte ptr [di+14h]	; intelligence	;@6DF2
	call PrintBcdByte	;@6DF5
	lea si, MsgZtWis	; "Wis..."	;@6DF8
	call PrintMsg	;@6DFC
	mov al, byte ptr [di+15h]	; wisdom	;@6DFF
	call PrintBcdByte	;@6E02
	lea si, MsgZtHP	; "H.P..."	;@6E05
	call PrintMsg	;@6E09
	mov ax, word ptr [di+1Ah]	; hit points	;@6E0C
	call PrintBcdWord	;@6E0F
	call WaitMore	;@6E12
	cmp al, 0	;@6E15
	je ShowZtats_MaxHP	;@6E17
	jmp ShowZtats_Done	;@6E19
ShowZtats_MaxHP:	lea si, MsgZtHM	; "H.M..."	;@6E1C
	call PrintMsg	;@6E20
	mov ax, word ptr [di+1Ch]	; maximum hit points	;@6E23
	call PrintBcdWord	;@6E26
	call WaitMore	;@6E29
	cmp al, 0	;@6E2C
	je ShowZtats_Gold	;@6E2E
	jmp ShowZtats_Done	;@6E30
ShowZtats_Gold:	lea si, MsgZtGold	; "Gold: "	;@6E33
	call PrintMsg	;@6E37
	mov ax, word ptr [di+23h]	; gold	;@6E3A
	call PrintBcdWord	;@6E3D
	call WaitMore	;@6E40
	cmp al, 0	;@6E43
	je ShowZtats_Exp	;@6E45
	jmp ShowZtats_Done	;@6E47
ShowZtats_Exp:	lea si, MsgZtExp	; "Exp..."	;@6E4A
	call PrintMsg	;@6E4E
	mov ax, word ptr [di+1Eh]	; experience	;@6E51
	call PrintBcdWord	;@6E54
	call WaitMore	;@6E57
	cmp al, 0	;@6E5A
	je ShowZtats_Gems	;@6E5C
	jmp ShowZtats_Done	;@6E5E
ShowZtats_Gems:	lea si, MsgZtGems	; "Gems.."	;@6E61
	call PrintMsg	;@6E65
	mov al, byte ptr [di+25h]	; gems	;@6E68
	call PrintBcdByte	;@6E6B
	call WaitMore	;@6E6E
	cmp al, 0	;@6E71
	je ShowZtats_Keys	;@6E73
	jmp ShowZtats_Done	;@6E75
ShowZtats_Keys:	lea si, MsgZtKeys	; "Keys.."	;@6E78
	call PrintMsg	;@6E7C
	mov al, byte ptr [di+26h]	; keys	;@6E7F
	call PrintBcdByte	;@6E82
	call WaitMore	;@6E85
	cmp al, 0	;@6E88
	je ShowZtats_Powd	;@6E8A
	jmp ShowZtats_Done	;@6E8C
ShowZtats_Powd:	lea si, MsgZtPowd	; "Powd.."	;@6E8F
	call PrintMsg	;@6E93
	mov al, byte ptr [di+27h]	; powders	;@6E96
	call PrintBcdByte	;@6E99
	call WaitMore	;@6E9C
	cmp al, 0	;@6E9F
	je ShowZtats_Trch	;@6EA1
	jmp ShowZtats_Done	;@6EA3
ShowZtats_Trch:	lea si, MsgZtTrch	; "Trch.."	;@6EA6
	call PrintMsg	;@6EAA
	mov al, byte ptr [di+0Fh]	; torches	;@6EAD
	call PrintBcdByte	;@6EB0
	call WaitMore	;@6EB3
	cmp al, 0	;@6EB6
	je ShowZtats_Marks	;@6EB8
	jmp ShowZtats_Done	;@6EBA
ShowZtats_Marks:	mov cx, 8	;@6EBD
	mov ah, byte ptr [di+0Eh]	; marks (bits 7-4) and cards (bits 3-0)	;@6EC0
	mov bx, 0	;@6EC3
ShowZtats_MarkLoop:	rcl ah, 1	; bit 7 first	;@6EC6
	jae ShowZtats_MarkNext	;@6EC8
	mov si, word ptr MarkCardNames[bx]	;@6ECA
	call PrintMsg	;@6ECE
	call WaitMore	;@6ED1
	cmp al, 0	;@6ED4
	je ShowZtats_MarkNext	;@6ED6
	jmp ShowZtats_Done	;@6ED8
ShowZtats_MarkNext:	add bx, 2	;@6EDB
	loop ShowZtats_MarkLoop	;@6EDE
	lea si, MsgZtWeapon	; "Weapon:"	;@6EE0
	call PrintMsg	;@6EE4
	mov al, byte ptr [di+30h]	; weapon readied	;@6EE7
	add al, 41h	; name 40h+n: the weapons	;@6EEA
	call PrintName	;@6EEC
	call WaitMore	;@6EEF
	cmp al, 0	;@6EF2
	je ShowZtats_Armour	;@6EF4
	jmp ShowZtats_Done	;@6EF6
ShowZtats_Armour:	lea si, MsgZtArmour	; "Armour:"	;@6EF9
	call PrintMsg	;@6EFD
	mov al, byte ptr [di+28h]	; armour worn	;@6F00
	add al, 51h	; name 50h+n: the armours	;@6F03
	call PrintName	;@6F05
	call WaitMore	;@6F08
	cmp al, 0	;@6F0B
	je ShowZtats_Weapons	;@6F0D
	jmp ShowZtats_Done	;@6F0F
ShowZtats_Weapons:	lea si, MsgZtWeapons	; "***Weapons***"	;@6F12
	call PrintMsg	;@6F16
	mov bx, 0Fh	; weapons 15 (Exotic) down to 1 (Dagger)	;@6F19
ShowZtats_WpnLoop:	cmp byte ptr [bx+di+30h], 0	; count owned (31h-3Fh)	;@6F1C
	je ShowZtats_WpnNext	;@6F20
	call ScrollMsg	;@6F22
	mov al, byte ptr [bx+di+30h]	;@6F25
	call PrintBcdByte	;@6F28
	mov al, 2Dh	; '-'	;@6F2B
	call PutChar	;@6F2D
	mov al, bl	;@6F30
	add al, 41h	;@6F32
	call PrintName	;@6F34
	mov al, 2Dh	;@6F37
	call PutChar	;@6F39
	mov al, 28h	; '('	;@6F3C
	call PutChar	;@6F3E
	mov al, bl	;@6F41
	add al, 41h	; the menu key 'A'+n	;@6F43
	call PutChar	;@6F45
	mov al, 29h	;@6F48
	call PutChar	;@6F4A
	call WaitMore	;@6F4D
	cmp al, 0FFh	;@6F50
	je ShowZtats_Done	;@6F52
ShowZtats_WpnNext:	dec bl	;@6F54
	jne ShowZtats_WpnLoop	;@6F56
	lea si, MsgZtHandsArmour	; "02-Hands-(A)", "**Armour**"	;@6F58
	call PrintMsg	;@6F5C
	mov bx, 7	; armours 7 (Exotic) down to 1 (Cloth)	;@6F5F
ShowZtats_ArmLoop:	cmp byte ptr [bx+di+28h], 0	; count owned (29h-2Fh)	;@6F62
	je ShowZtats_ArmNext	;@6F66
	call ScrollMsg	;@6F68
	mov al, byte ptr [bx+di+28h]	;@6F6B
	call PrintBcdByte	;@6F6E
	mov al, 2Dh	;@6F71
	call PutChar	;@6F73
	mov al, bl	;@6F76
	add al, 51h	;@6F78
	call PrintName	;@6F7A
	mov al, 2Dh	;@6F7D
	call PutChar	;@6F7F
	mov al, 28h	;@6F82
	call PutChar	;@6F84
	mov al, bl	;@6F87
	add al, 41h	;@6F89
	call PutChar	;@6F8B
	mov al, 29h	;@6F8E
	call PutChar	;@6F90
	call WaitMore	;@6F93
	cmp al, 0FFh	;@6F96
	je ShowZtats_Done	;@6F98
ShowZtats_ArmNext:	dec bl	;@6F9A
	jne ShowZtats_ArmLoop	;@6F9C
	lea si, MsgZtSkin	; "01-Skin-(A)"	;@6F9E
	call PrintMsg	;@6FA2
ShowZtats_Done:	mov al, dh	;@6FA5
	sub al, 30h	;@6FA7
	call InvertPlayerNum	;@6FA9
	pop si	;@6FAC
	pop bx	;@6FAD
	pop ax	;@6FAE
	popf	;@6FAF
	ret	;@6FB0
;------------------------------------------------------------------------------
; WaitMore: wait for Enter, Down or Space (AL = 0, go on) or Esc (scroll a line,
; AL = 0FFh, stop); other keys are ignored. Out: AL; AH kept. Uses: nothing else.
;------------------------------------------------------------------------------
WaitMore:	pushf	;@6FB1
	push bx	;@6FB2
	mov bh, ah	;@6FB3
WaitMore_Loop:	call KeyReady	;@6FB5
	je WaitMore_Loop	;@6FB8
	call ReadKey	;@6FBA
	cmp ax, 1C0Dh	; Enter	;@6FBD
	je WaitMore_Go	;@6FC0
	cmp ax, 5000h	; Down	;@6FC2
	je WaitMore_Go	;@6FC5
	cmp ax, 3920h	; Space	;@6FC7
	je WaitMore_Go	;@6FCA
	cmp ax, 11Bh	; Esc	;@6FCC
	jne WaitMore_Loop	;@6FCF
	call ScrollMsg	;@6FD1
	mov al, 0FFh	;@6FD4
	jmp short WaitMore_Done	;@6FD6
WaitMore_Go:	mov al, 0	;@6FD8
WaitMore_Done:	mov ah, bh	;@6FDA
	pop bx	;@6FDC
	popf	;@6FDD
	ret	;@6FDE
;------------------------------------------------------------------------------
; PartyUpkeep: called once a turn (main loop, dungeon, combat). On the surface it runs
; every time, elsewhere every 4th call (counter UpkeepTick). For each player that is up, from the
; fourth to the first: one magic point if below the class's limit (Wizard: Int; Cleric: Wis;
; Lark, Druid, Alchemist: Int/2; Paladin, Illusionist, Druid: Wis/2 (a Druid can gain two);
; Ranger: the smaller of Int/2 and Wis/2), then 0.10 food (SpendFood); a poisoned player loses
; one hit point ("Poisoned!", his box flashes); every 10th run (counter RegenTick) one hit point
; back, up to the maximum. Then StatusLine. Uses: nothing.
;------------------------------------------------------------------------------
PartyUpkeep:	pushf	;@6FDF
	push ax	;@6FE0
	push bx	;@6FE1
	push cx	;@6FE2
	push si	;@6FE3
	cmp byte ptr Location, 0	; Sosaria	;@6FE4
	je PartyUpkeep_Start	;@6FE9
	dec byte ptr UpkeepTick	;@6FEB
	je PartyUpkeep_Reset4	;@6FEF
	jmp PartyUpkeep_Done	;@6FF1
PartyUpkeep_Reset4:	mov byte ptr UpkeepTick, 4	;@6FF4
PartyUpkeep_Start:	lea bx, Player4	; Players + 0C0h: the fourth record	;@6FF9
	mov cx, 4	;@6FFD
	dec byte ptr RegenTick	; 9 ... 0: heal at 0	;@7000
	jns PartyUpkeep_Loop	;@7004
	mov byte ptr RegenTick, 9	;@7006
PartyUpkeep_Loop:	call IsUp	;@700B
	je PartyUpkeep_Wizard	;@700E
	jmp PartyUpkeep_Next	;@7010
PartyUpkeep_Wizard:	cmp byte ptr [bx+17h], 57h	; class 'W'	;@7013
	jne PartyUpkeep_Cleric	;@7017
	mov al, byte ptr [bx+19h]	; magic points	;@7019
	cmp al, byte ptr [bx+14h]	; intelligence	;@701C
	jae PartyUpkeep_Cleric	;@701F
	call AddMagicPoint	;@7021
PartyUpkeep_Cleric:	cmp byte ptr [bx+17h], 43h	; 'C'	;@7024
	jne PartyUpkeep_TryLark	;@7028
	mov al, byte ptr [bx+19h]	;@702A
	cmp al, byte ptr [bx+15h]	; wisdom	;@702D
	jae PartyUpkeep_TryLark	;@7030
	call AddMagicPoint	;@7032
PartyUpkeep_TryLark:	cmp byte ptr [bx+17h], 4Ch	; 'L' Lark	;@7035
	je PartyUpkeep_HalfInt	;@7039
	cmp byte ptr [bx+17h], 44h	; 'D' Druid	;@703B
	je PartyUpkeep_HalfInt	;@703F
	cmp byte ptr [bx+17h], 41h	; 'A' Alchemist	;@7041
	jne PartyUpkeep_TryPaladin	;@7045
PartyUpkeep_HalfInt:	mov al, byte ptr [bx+14h]	; intelligence	;@7047
	call HalveBcd	;@704A
	cmp al, byte ptr [bx+19h]	;@704D
	jbe PartyUpkeep_TryPaladin	;@7050
	call AddMagicPoint	;@7052
PartyUpkeep_TryPaladin:	cmp byte ptr [bx+17h], 50h	; 'P' Paladin	;@7055
	je PartyUpkeep_HalfWis	;@7059
	cmp byte ptr [bx+17h], 49h	; 'I' Illusionist	;@705B
	je PartyUpkeep_HalfWis	;@705F
	cmp byte ptr [bx+17h], 44h	; 'D' Druid again	;@7061
	jne PartyUpkeep_TryRanger	;@7065
PartyUpkeep_HalfWis:	mov al, byte ptr [bx+15h]	; wisdom	;@7067
	call HalveBcd	;@706A
	cmp al, byte ptr [bx+19h]	;@706D
	jbe PartyUpkeep_TryRanger	;@7070
	call AddMagicPoint	;@7072
PartyUpkeep_TryRanger:	cmp byte ptr [bx+17h], 52h	; 'R' Ranger	;@7075
	jne PartyUpkeep_Food	;@7079
	mov al, byte ptr [bx+15h]	;@707B
	call HalveBcd	;@707E
	cmp al, byte ptr [bx+19h]	;@7081
	jbe PartyUpkeep_Food	;@7084
	mov al, byte ptr [bx+14h]	;@7086
	call HalveBcd	;@7089
	cmp al, byte ptr [bx+19h]	;@708C
	jbe PartyUpkeep_Food	;@708F
	call AddMagicPoint	;@7091
PartyUpkeep_Food:	mov al, 10h	; 0.10 food (BCD hundredths)	;@7094
	call SpendFood	;@7096
	cmp byte ptr [bx+11h], 50h	; 'P' poisoned	;@7099
	jne PartyUpkeep_Heal	;@709D
	mov al, 1	;@709F
	call HurtPlayer	; one hit point (can kill)	;@70A1
	mov al, cl	;@70A4
	dec al	; player 0-3	;@70A6
	call FlashPlayer	;@70A8
	lea si, MsgPoisoned	; "Poisoned!"	;@70AB
	call PrintMsg	;@70AF
	call FlashPlayer	; flash back	;@70B2
PartyUpkeep_Heal:	cmp byte ptr RegenTick, 0	;@70B5
	jne PartyUpkeep_Next	;@70BA
	mov ax, word ptr [bx+1Ah]	; hit points	;@70BC
	cmp ax, word ptr [bx+1Ch]	; maximum	;@70BF
	jae PartyUpkeep_Next	;@70C2
	add al, 1	;@70C4
	daa	;@70C6
	xchg ah, al	;@70C7
	adc al, 0	;@70C9
	daa	;@70CB
	xchg ah, al	;@70CC
	mov word ptr [bx+1Ah], ax	;@70CE
PartyUpkeep_Next:	sub bx, 40h	;@70D1
	dec cl	;@70D4
	je PartyUpkeep_Status	;@70D6
	jmp PartyUpkeep_Loop	;@70D8
PartyUpkeep_Status:	call StatusLine	;@70DB
PartyUpkeep_Done:	pop si	;@70DE
	pop cx	;@70DF
	pop bx	;@70E0
	pop ax	;@70E1
	popf	;@70E2
	ret	;@70E3
;------------------------------------------------------------------------------
; SpendFood: subtract AL hundredths (BCD) from the food of the player at BX (bytes 20h-22h).
; When it runs out: food 0, "Starving!", the player's box flashes with sound 0F7h, and he
; takes 5 hit points of damage (HurtPlayer). In: AL, BX. Uses: nothing.
;------------------------------------------------------------------------------
SpendFood:	pushf	;@70E4
	push ax	;@70E5
	push cx	;@70E6
	push si	;@70E7
	mov ah, al	;@70E8
	mov al, byte ptr [bx+20h]	; food, hundredths	;@70EA
	sub al, ah	;@70ED
	das	;@70EF
	mov byte ptr [bx+20h], al	;@70F0
	mov ax, word ptr [bx+21h]	; food (BCD word), minus the borrow	;@70F3
	sbb al, 0	;@70F6
	das	;@70F8
	xchg al, ah	;@70F9
	sbb al, 0	;@70FB
	das	;@70FD
	xchg al, ah	;@70FE
	mov word ptr [bx+21h], ax	;@7100
	jae SpendFood_Done	;@7103
	mov word ptr [bx+21h], 0	;@7105
	lea si, MsgStarving	; "Starving!"	;@710A
	call PrintMsg	;@710E
	lea si, Players	;@7111
	mov ax, bx	;@7115
	sub ax, si	;@7117
	mov cl, 40h	;@7119
	div cl	; AL = player 0-3	;@711B
	call FlashPlayer	;@711D
	mov ah, al	;@7120
	mov al, 0F7h	; hit sound	;@7122
	call Sound	;@7124
	mov al, ah	;@7127
	call FlashPlayer	;@7129
	mov al, 5	; 5 hit points	;@712C
	call HurtPlayer	;@712E
SpendFood_Done:	pop si	;@7131
	pop cx	;@7132
	pop ax	;@7133
	popf	;@7134
	ret	;@7135
;------------------------------------------------------------------------------
; AddMagicPoint: one more magic point (BCD, no cap) for the player at BX if he is up.
;------------------------------------------------------------------------------
AddMagicPoint:	pushf	;@7136
	push ax	;@7137
	call IsUp	;@7138
	jne AddMagicPoint_Done	;@713B
	mov al, byte ptr [bx+19h]	; magic points	;@713D
	add al, 1	;@7140
	daa	;@7142
	mov byte ptr [bx+19h], al	;@7143
AddMagicPoint_Done:	pop ax	;@7146
	popf	;@7147
	ret	;@7148
;------------------------------------------------------------------------------
; HalveBcd: AL = AL / 2, both BCD (unpack, aad, shift, aam, repack). AH kept.
;------------------------------------------------------------------------------
HalveBcd:	pushf	;@7149
	push bx	;@714A
	push ax	;@714B
	mov bh, ah	;@714C
	mov ah, 0	;@714E
	mov bl, al	;@7150
	shl ax, 1	;@7152
	shl ax, 1	;@7154
	shl ax, 1	;@7156
	shl ax, 1	; AH = tens digit	;@7158
	mov al, bl	;@715A
	and al, 0Fh	; AL = units digit	;@715C
	aad	; binary	;@715E
	shr ax, 1	;@7160
	aam	; back to two digits	;@7162
	shl ah, 1	;@7164
	shl ah, 1	;@7166
	shl ah, 1	;@7168
	shl ah, 1	;@716A
	or al, ah	;@716C
	mov bl, al	;@716E
	pop ax	;@7170
	mov al, bl	;@7171
	pop bx	;@7173
	popf	;@7174
	ret	;@7175
;------------------------------------------------------------------------------
; FlashPlayer: invert the status box of player AL (0-3): character rows 4*AL+1 to
; 4*AL+3, 15 cells from column 18h (screen offset (4*AL+1)*320 + 30h, 12 scan line pairs).
; Called twice around a sound or message to make the box flash. In: AL. Uses: nothing.
;------------------------------------------------------------------------------
FlashPlayer:	pushf	;@7176
	push ax	;@7177
	push bx	;@7178
	push cx	;@7179
	push dx	;@717A
	push ds	;@717B
	mov ds, word ptr ds:[4F39h]	; the screen segment (B800)	;@717C
	mov dl, 0Ch	; 12 lines in each bank	;@7180
	mov bl, al	;@7182
	mov bh, 0	;@7184
	shl bx, 1	;@7186
	shl bx, 1	;@7188
	inc bx	;@718A
	shl bx, 1	;@718B
	shl bx, 1	;@718D
	shl bx, 1	;@718F
	shl bx, 1	;@7191
	mov ax, bx	;@7193
	shl bx, 1	;@7195
	shl bx, 1	;@7197
	add bx, ax	;@7199
	shl bx, 1	;@719B
	shl bx, 1	;@719D
	add bx, 30h	; column 18h	;@719F
FlashPlayer_Row:	mov cx, 0Fh	; 15 cells	;@71A2
FlashPlayer_Word:	xor word ptr [bx], 0FFFFh	; even line	;@71A5
	xor word ptr [bx+2000h], 0FFFFh	; odd line	;@71A9
	inc bx	;@71AF
	inc bx	;@71B0
	loop FlashPlayer_Word	;@71B1
	add bx, 32h	;@71B3
	dec dl	;@71B6
	jne FlashPlayer_Row	;@71B8
	pop ds	;@71BA
	pop dx	;@71BB
	pop cx	;@71BC
	pop bx	;@71BD
	pop ax	;@71BE
	popf	;@71BF
	ret	;@71C0
;------------------------------------------------------------------------------
; FlashView: invert the map window (176 x 176 pixels from scan line 8, pixel 8).
; Called in pairs around a sound: spells, force fields, Lord British. Uses: nothing.
;------------------------------------------------------------------------------
FlashView:	pushf	;@71C1
	push bx	;@71C2
	push cx	;@71C3
	push dx	;@71C4
	push ds	;@71C5
	mov ds, word ptr ds:[4F39h]	; the screen segment	;@71C6
	mov bx, 142h	; line 8 (4 * 80), byte 2	;@71CA
	mov dx, 58h	; 88 lines in each bank	;@71CD
FlashView_Row:	mov cx, 16h	; 22 words = 176 pixels	;@71D0
FlashView_Word:	xor word ptr [bx], 0FFFFh	;@71D3
	xor word ptr [bx+2000h], 0FFFFh	;@71D7
	inc bx	;@71DD
	inc bx	;@71DE
	loop FlashView_Word	;@71DF
	add bx, 24h	;@71E1
	dec dx	;@71E4
	jne FlashView_Row	;@71E5
	pop ds	;@71E7
	pop dx	;@71E8
	pop cx	;@71E9
	pop bx	;@71EA
	popf	;@71EB
	ret	;@71EC
;------------------------------------------------------------------------------
; InvertPlayerNum: invert the digit of player AL (1-4) in the frame (character row
; 4*(AL-1), column 1Fh: screen offset (AL-1)*500h + 3Eh, 8 scan lines). Called in pairs:
; it marks the player whose Ztats are shown, who talks, or whose turn it is in a fight.
; In: AL. Uses: nothing.
;------------------------------------------------------------------------------
InvertPlayerNum:	pushf	;@71ED
	push bx	;@71EE
	push ds	;@71EF
	mov ds, word ptr ds:[4F39h]	; the screen segment	;@71F0
	mov bh, al	;@71F4
	dec bh	;@71F6
	shl bh, 1	;@71F8
	shl bh, 1	;@71FA
	add bh, al	;@71FC
	dec bh	; BH = 5 * (AL-1): BX = (AL-1) * 500h	;@71FE
	mov bl, 3Eh	; column 1Fh	;@7200
	xor word ptr [bx], 0FFFFh	;@7202
	xor word ptr [bx+50h], 0FFFFh	;@7206
	xor word ptr [bx+0A0h], 0FFFFh	;@720B
	xor word ptr [bx+0F0h], 0FFFFh	;@7211
	xor word ptr [bx+2000h], 0FFFFh	;@7217
	xor word ptr [bx+2050h], 0FFFFh	;@721D
	xor word ptr [bx+20A0h], 0FFFFh	;@7223
	xor word ptr [bx+20F0h], 0FFFFh	;@7229
	pop ds	;@722F
	pop bx	;@7230
	popf	;@7231
	ret	;@7232
;------------------------------------------------------------------------------
; AgainstWind: may the party move in direction AL (1 north, 2 east, 3 south, 4 west)?
; Only a frigate is limited: not at all when the wind is calm (WindDir 0), and not into the
; wind (AL = WindDir, the side the wind comes from). Out: AL = 0FFh and ZF clear = no.
;------------------------------------------------------------------------------
AgainstWind:	pushf	;@7233
	cmp byte ptr PartyTile, 0Bh	; frigate	;@7234
	jne AgainstWind_No	;@7239
	cmp byte ptr WindDir, 0	; calm	;@723B
	je AgainstWind_Yes	;@7240
	cmp al, byte ptr WindDir	;@7242
	jne AgainstWind_No	;@7246
AgainstWind_Yes:	mov al, 0FFh	;@7248
	jmp short AgainstWind_Done	;@724A
AgainstWind_No:	mov al, 0	;@724C
AgainstWind_Done:	popf	;@724E
	cmp al, 0	;@724F
	ret	;@7251
;------------------------------------------------------------------------------
; Hang: loop forever. The end of the game: all players out (CheckAllOut) and the last
; screen of ENDING. Only a reboot leaves it.
;------------------------------------------------------------------------------
Hang:	jmp Hang	;@7252
;------------------------------------------------------------------------------
; CheckTerrain: may the party enter a cell of shape AL (FORMATS.md 2)? A frigate
; sails on water and whirlpools only. On foot or horseback: grass, brush, forest, dungeon,
; towne, castle, floor, chest, horse, frigate (1-11 except 4 mountains), moon gates and
; shrines; the step sound plays (twice more on a horse). A force field stops the party and
; burns the first player without the Mark of Force (99 hit points; all marked: they pass); lava
; burns every player up without the Mark of Fire (50) and lets the party pass.
; In: AL. Out: AL = 0 and ZF set = may enter. Uses: nothing else.
;------------------------------------------------------------------------------
CheckTerrain:	pushf	;@7254
	push bx	;@7255
	push ax	;@7256
	push cx	;@7257
	cmp byte ptr PartyTile, 0Bh	; frigate	;@7258
	jne CheckTerrain_Land	;@725D
	cmp al, 0	; water	;@725F
	je CheckTerrain_Ok	;@7261
	cmp al, 0Ch	; whirlpool	;@7263
	je CheckTerrain_Ok	;@7265
	jmp short CheckTerrain_No	;@7267
CheckTerrain_Land:	cmp al, 20h	; force field	;@7269
	je CheckTerrain_Force	;@726B
	cmp al, 21h	; lava	;@726D
	je CheckTerrain_ToLava	;@726F
	cmp al, 22h	; moon gate	;@7271
	je CheckTerrain_Step	;@7273
	cmp al, 3Eh	; shrine	;@7275
	je CheckTerrain_Step	;@7277
	cmp al, 0Ch	; whirlpool and up: creatures, walls ...	;@7279
	jae CheckTerrain_No	;@727B
	cmp al, 0	; water	;@727D
	je CheckTerrain_No	;@727F
	cmp al, 4	; mountains	;@7281
	je CheckTerrain_No	;@7283
CheckTerrain_Step:	mov al, 0F6h	; step sound	;@7285
	call Sound	;@7287
	mov cx, 2000h	;@728A
CheckTerrain_Wait1:	loop CheckTerrain_Wait1	; delay (CPU speed dependent)	;@728D
	call Sound	;@728F
	cmp byte ptr PartyTile, 0Ah	; horse: a third hoof beat	;@7292
	jne CheckTerrain_Ok	;@7297
	mov cx, 2000h	;@7299
CheckTerrain_Wait2:	loop CheckTerrain_Wait2	;@729C
	call Sound	;@729E
CheckTerrain_Ok:	mov al, 0	;@72A1
	jmp short CheckTerrain_Done	;@72A3
CheckTerrain_No:	mov al, 0FFh	;@72A5
CheckTerrain_Done:	pop cx	;@72A7
	mov bl, al	;@72A8
	pop ax	;@72AA
	mov al, bl	;@72AB
	pop bx	;@72AD
	popf	;@72AE
	cmp al, 0	;@72AF
	ret	;@72B1
CheckTerrain_ToLava:	jmp short CheckTerrain_Lava	;@72B2
CheckTerrain_Force:	call FlashView	; flash the map window	;@72B4
	mov al, 0FCh	; ? a buzz, BL = its length	;@72B7
	mov bl, 10h	;@72B9
	call Sound	;@72BB
	mov cl, byte ptr PartySize	;@72BE
	mov ch, 0	;@72C2
	lea bx, Players	;@72C4
CheckTerrain_ForceLoop:	test byte ptr [bx+0Eh], 10h	; Mark of Force	;@72C8
	je CheckTerrain_ForceHit	;@72CC
	add bx, 40h	;@72CE
	loop CheckTerrain_ForceLoop	;@72D1
	call FlashView	;@72D3
	jmp CheckTerrain_Step	;@72D6
CheckTerrain_ForceHit:	mov al, 99h	; 99 hit points (dead or not: no IsUp test)	;@72D8
	call HurtPlayer	;@72DA
	mov al, byte ptr PartySize	;@72DD
	sub al, cl	; player 0-3	;@72E0
	call FlashPlayer	;@72E2
	mov ah, al	;@72E5
	mov al, 0F7h	; hit sound	;@72E7
	call Sound	;@72E9
	mov al, ah	;@72EC
	call FlashPlayer	;@72EE
	call FlashView	;@72F1
	call StatusLine	;@72F4
	jmp CheckTerrain_No	;@72F7
CheckTerrain_Lava:	mov al, 0F8h	; ? the lava sound	;@72F9
	call Sound	;@72FB
	lea bx, Players	;@72FE
	mov cl, byte ptr PartySize	;@7302
	mov ch, 0	;@7306
CheckTerrain_LavaLoop:	call IsUp	;@7308
	jne CheckTerrain_LavaNext	;@730B
	test byte ptr [bx+0Eh], 20h	; Mark of Fire	;@730D
	jne CheckTerrain_LavaNext	;@7311
	mov al, 50h	; 50 hit points	;@7313
	call HurtPlayer	;@7315
	mov al, byte ptr PartySize	;@7318
	sub al, cl	; player 0-3	;@731B
	call FlashPlayer	;@731D
	mov ah, al	;@7320
	mov al, 0F7h	; hit sound	;@7322
	call Sound	;@7324
	mov al, ah	;@7327
	call FlashPlayer	;@7329
CheckTerrain_LavaNext:	add bx, 40h	;@732C
	loop CheckTerrain_LavaLoop	;@732F
	call StatusLine	;@7331
	jmp CheckTerrain_Ok	;@7334
; The whirlpool's step (x, y) for its 8 directions: S, SE, E, NE, N, NW, W, SW.
WhirlDxTbl label byte
	db 0h,1h,1h,1h,0h,0FFh,0FFh,0FFh	;@7337
WhirlDyTbl label byte
	db 1h,1h,0h,0FFh,0FFh,0FFh,0h,1h	;@733F
;------------------------------------------------------------------------------
; MoveWhirlpool: called while the main loop waits for a key. On Sosaria, every 4th
; call (counter WhirlpoolTick), the whirlpool (position in the word at 1320h, named WhirlpoolX; step
; in WhirlpoolDX/WhirlpoolDY) moves: 1 time in 8, or when the next cell is neither water nor a frigate,
; it picks a new direction instead. Onto water it simply moves; onto a frigate (map byte 2Ch)
; it destroys it: "A ship was Destroyed!". Map bytes are shape * 4: 30h whirlpool, 0 water.
; If it reaches the party, Whirlpool takes the party (to Ambrosia) and BL gets a new key wait
; deadline (seconds + 5) for the caller's loop. In: BL = the caller's deadline.
; Out: BX kept or BL renewed. Uses: nothing else.
;------------------------------------------------------------------------------
MoveWhirlpool:	pushf	;@7347
	push ax	;@7348
	push cx	;@7349
	push dx	;@734A
	push si	;@734B
	push bx	;@734C
	cmp byte ptr Location, 0	; Sosaria	;@734D
	je MoveWhirlpool_Count	;@7352
MoveWhirlpool_Exit:	jmp MoveWhirlpool_Done	;@7354
MoveWhirlpool_Count:	dec byte ptr WhirlpoolTick	;@7357
	jne MoveWhirlpool_Exit	;@735B
	mov byte ptr WhirlpoolTick, 4	;@735D
	mov dh, 8	;@7362
	call Random	;@7364
	cmp dl, 0	; 1 in 8: turn	;@7367
	je MoveWhirlpool_Turn	;@736A
	mov cx, word ptr WhirlpoolX	; the whirlpool's x, y	;@736C
	add ch, byte ptr WhirlpoolDY	; + dy	;@7370
	add cl, byte ptr WhirlpoolDX	; + dx	;@7374
	and cx, 3F3Fh	; the map wraps at 64	;@7378
	mov bx, cx	;@737C
	call MapCellAddr	;@737E
	cmp al, 0	; water	;@7381
	je MoveWhirlpool_Move	;@7383
	cmp al, 2Ch	; a frigate (shape 0Bh)	;@7385
	jne MoveWhirlpool_Turn	;@7387
	mov byte ptr [bx], 30h	; whirlpool (shape 0Ch)	;@7389
	mov bx, word ptr WhirlpoolX	;@738C
	mov word ptr WhirlpoolX, cx	;@7390
	call MapCellAddr	;@7394
	mov byte ptr [bx], 0	; water where it was	;@7397
	cmp cx, word ptr PlayerXY	;@739A
	je MoveWhirlpool_Hit	;@739E
	call BuildView	;@73A0
	mov al, 0F4h	;@73A3
	call Sound	;@73A5
	lea si, MsgShipDestroyed	; "A ship was Destroyed!"	;@73A8
	call PrintMsg	;@73AC
	jmp short MoveWhirlpool_Done	;@73AF
MoveWhirlpool_Turn:	mov dh, 8	;@73B1
	call Random	;@73B3
	mov bl, dl	;@73B6
	mov bh, 0	;@73B8
	mov al, byte ptr WhirlDxTbl[bx]	;@73BA
	mov byte ptr WhirlpoolDX, al	;@73BE
	mov al, byte ptr WhirlDyTbl[bx]	;@73C1
	mov byte ptr WhirlpoolDY, al	;@73C5
	jmp short MoveWhirlpool_Check	;@73C8
MoveWhirlpool_Move:	mov byte ptr [bx], 30h	; whirlpool	;@73CA
	mov bx, word ptr WhirlpoolX	;@73CD
	mov word ptr WhirlpoolX, cx	;@73D1
	call MapCellAddr	;@73D5
	mov byte ptr [bx], 0	; water	;@73D8
	call BuildView	;@73DB
MoveWhirlpool_Check:	mov ax, word ptr WhirlpoolX	;@73DE
	cmp ax, word ptr PlayerXY	;@73E1
	jne MoveWhirlpool_Done	;@73E5
MoveWhirlpool_Hit:	call Whirlpool	; the whirlpool takes the party	;@73E7
	mov al, 10h	; the prompt character, as in the main loop	;@73EA
	call PutChar	;@73EC
	pop bx	;@73EF
	mov ah, 2Ch	; get time: meant int 21h (the main loop uses it);	;@73F0
	int 15h	; int 15h AH=2Ch is no DOS call: DH probably unchanged (bug)	;@73F2
	mov bl, dh	; seconds + 5, mod 60	;@73F4
	add bl, 5	;@73F6
	cmp bl, 3Ch	;@73F9
	jb MoveWhirlpool_Ret	;@73FC
	sub bl, 3Ch	;@73FE
	jmp short MoveWhirlpool_Ret	;@7401
MoveWhirlpool_Done:	pop bx	;@7403
MoveWhirlpool_Ret:	pop si	;@7404
	pop dx	;@7405
	pop cx	;@7406
	pop ax	;@7407
	popf	;@7408
	ret	;@7409
;------------------------------------------------------------------------------
; UpcaseBuf: turn the CX characters at DI to upper case. Uses: nothing.
;------------------------------------------------------------------------------
UpcaseBuf:	pushf	;@740A
	push cx	;@740B
	push di	;@740C
	jcxz UpcaseBuf_Done	;@740D
UpcaseBuf_Loop:	cmp byte ptr [di], 61h	; 'a'	;@740F
	jb UpcaseBuf_Next	;@7412
	cmp byte ptr [di], 7Ah	; 'z'	;@7414
	ja UpcaseBuf_Next	;@7417
	add byte ptr [di], 0E0h	; - 20h	;@7419
UpcaseBuf_Next:	inc di	;@741C
	loop UpcaseBuf_Loop	;@741D
UpcaseBuf_Done:	pop di	;@741F
	pop cx	;@7420
	popf	;@7421
	ret	;@7422
;------------------------------------------------------------------------------
; MatchWord: do the CX characters typed at DI spell the word at SI (ended by a space,
; as in the padded list "EVOCARE   INSERT    DIG ...")? Leading and trailing spaces are
; allowed, nothing else. In: SI, DI, CX. Out: AL = 0FFh match, 0 not. Uses: nothing else.
;------------------------------------------------------------------------------
MatchWord:	pushf	;@7423
	push cx	;@7424
	push si	;@7425
	push di	;@7426
	jcxz MatchWord_No	;@7427
MatchWord_Skip:	cmp byte ptr [di], 20h	; leading spaces	;@7429
	jne MatchWord_Cmp	;@742C
	inc di	;@742E
	loop MatchWord_Skip	;@742F
	jmp short MatchWord_No	;@7431
MatchWord_Cmp:	mov al, byte ptr [si]	;@7433
	cmp al, byte ptr [di]	;@7435
	jne MatchWord_No	;@7437
	cmp byte ptr [si+1], 20h	;@7439
	je MatchWord_TailNext	;@743D
	inc si	;@743F
	inc di	;@7440
	loop MatchWord_Cmp	;@7441
	jmp short MatchWord_No	;@7443
MatchWord_Tail:	cmp byte ptr [di], 20h	;@7445
	jne MatchWord_No	;@7448
MatchWord_TailNext:	inc di	;@744A
	loop MatchWord_Tail	;@744B
	mov al, 0FFh	;@744D
	jmp short MatchWord_Done	;@744F
MatchWord_No:	mov al, 0	;@7451
MatchWord_Done:	pop di	;@7453
	pop si	;@7454
	pop cx	;@7455
	popf	;@7456
	ret	;@7457
CODE ENDS
END
